import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

const [first, second] = input;
const [n, k] = first.split(" ").map(Number);
const a = second.split(" ").map(Number);

// 最初の K 個の和から始め、窓を 1 つずつ右にずらす
let sum = 0;
for (let i = 0; i < k; i++) sum += a[i];
let best = sum;
for (let i = k; i < n; i++) {
  sum += a[i] - a[i - k]; // 入る要素を足し、出る要素を引く
  best = Math.max(best, sum);
}
console.log(best);
